### MassTransit Configuration with Outbox

**Program.cs:**

```csharp
using MassTransit;
using Microsoft.EntityFrameworkCore;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;
using Polly;
using Polly.RateLimit;

var builder = WebApplication.CreateBuilder(args);

// Add DbContext with Outbox
builder.Services.AddDbContext<ApplicationDbContext>(options =>
{
    options.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection"));
});

// Configure Schema Registry Service
builder.Services.AddSingleton<ISchemaRegistryService, SchemaRegistryService>();
builder.Services.Configure<SchemaRegistryOptions>(
    builder.Configuration.GetSection("SchemaRegistry"));

// Configure Rate Limiter
builder.Services.AddSingleton<IRateLimiterService, RateLimiterService>();
builder.Services.Configure<RateLimitingOptions>(
    builder.Configuration.GetSection("RateLimiting"));

// Configure AutoMapper
builder.Services.AddAutoMapper(typeof(IntegrationEventMappingProfile));

// Configure FluentValidation
builder.Services.AddValidatorsFromAssemblyContaining<Program>();

// Configure MassTransit with Outbox
builder.Services.AddMassTransit(x =>
{
    // Add Outbox
    x.AddEntityFrameworkOutbox<ApplicationDbContext>(o =>
    {
        o.UseSqlServer();
        o.UseBusOutbox();

        o.QueryDelay = TimeSpan.FromSeconds(
            builder.Configuration.GetValue<int>("TransactionalOutbox:PollingIntervalSeconds"));
        o.MessageDeliveryLimit = builder.Configuration.GetValue<int>("TransactionalOutbox:MaxRetries");
        o.DuplicateDetectionWindow = TimeSpan.FromDays(1);
    });

    // Configure Transport
    var transport = builder.Configuration.GetValue<string>("MassTransit:Transport");

    switch (transport?.ToLowerInvariant())
    {
        case "kafka":
            x.UsingKafka((context, cfg) =>
            {
                var kafkaConfig = builder.Configuration.GetSection("MassTransit:Kafka");

                cfg.Host(kafkaConfig.GetValue<string>("BootstrapServers"), h =>
                {
                    h.UseSasl(s =>
                    {
                        s.SecurityProtocol = SecurityProtocol.SaslSsl;
                        s.Mechanism = kafkaConfig.GetValue<string>("SaslMechanism");
                        s.Username = kafkaConfig.GetValue<string>("SaslUsername");
                        s.Password = kafkaConfig.GetValue<string>("SaslPassword");
                    });
                });

                // Producer Configuration
                cfg.ProducerConfig = new Dictionary<string, object>
                {
                    { "enable.idempotence", true },
                    { "max.in.flight.requests.per.connection", 5 },
                    { "acks", "all" },
                    { "message.timeout.ms", 30000 },
                    { "request.timeout.ms", 30000 }
                };

                cfg.ConfigurePublishTopology = true;
            });
            break;

        case "rabbitmq":
            x.UsingRabbitMq((context, cfg) =>
            {
                var rabbitConfig = builder.Configuration.GetSection("MassTransit:RabbitMQ");

                cfg.Host(rabbitConfig.GetValue<string>("Host"),
                         rabbitConfig.GetValue<string>("VirtualHost"), h =>
                {
                    h.Username(rabbitConfig.GetValue<string>("Username"));
                    h.Password(rabbitConfig.GetValue<string>("Password"));

                    if (rabbitConfig.GetValue<bool>("UseSsl"))
                    {
                        h.UseSsl(s =>
                        {
                            s.Protocol = SslProtocols.Tls12;
                        });
                    }
                });

                // Publisher Configuration
                cfg.PublisherConfirmation = rabbitConfig.GetValue<bool>("PublisherConfirms");
                cfg.ConfigurePublishTopology = true;
            });
            break;

        case "redis":
            x.UsingRedis((context, cfg) =>
            {
                var redisConfig = builder.Configuration.GetSection("MassTransit:Redis");

                cfg.Host(redisConfig.GetValue<string>("Configuration"));

                cfg.StreamConfiguration = new RedisStreamConfiguration
                {
                    MaxLength = redisConfig.GetValue<int>("MaxStreamLength"),
                    ReadTimeout = TimeSpan.FromMilliseconds(
                        redisConfig.GetValue<int>("StreamTimeout"))
                };
            });
            break;

        default:
            throw new InvalidOperationException($"Unsupported transport: {transport}");
    }
});

// Configure OpenTelemetry
builder.Services.AddOpenTelemetry()
    .WithTracing(tracing =>
    {
        tracing
            .SetResourceBuilder(ResourceBuilder.CreateDefault()
                .AddService(builder.Configuration.GetValue<string>("OpenTelemetry:ServiceName"))
                .AddAttributes(new Dictionary<string, object>
                {
                    ["service.version"] = builder.Configuration.GetValue<string>("OpenTelemetry:ServiceVersion"),
                    ["deployment.environment"] = builder.Environment.EnvironmentName
                }))
            .AddAspNetCoreInstrumentation()
            .AddEntityFrameworkCoreInstrumentation()
            .AddSource("MassTransit")
            .AddOtlpExporter(options =>
            {
                options.Endpoint = new Uri(
                    builder.Configuration.GetValue<string>("OpenTelemetry:OtlpEndpoint"));
            });
    });

var app = builder.Build();

// Ensure database and outbox table created
using (var scope = app.Services.CreateScope())
{
    var dbContext = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    await dbContext.Database.MigrateAsync();
}

app.Run();
```

