### Schema Registration Service

**SchemaRegistryService.cs:**

```csharp
using Amazon;
using Amazon.Glue;
using Amazon.Glue.Model;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Options;
using System.Text.Json;

public interface ISchemaRegistryService
{
    Task<string> RegisterSchemaAsync<T>(string schemaName, CancellationToken cancellationToken = default);
    Task<SchemaVersionMetadata> GetSchemaAsync(string schemaName, CancellationToken cancellationToken = default);
    Task ValidateCompatibilityAsync<T>(string schemaName, CancellationToken cancellationToken = default);
}

public class SchemaRegistryService : ISchemaRegistryService
{
    private readonly IAmazonGlue _glueClient;
    private readonly IMemoryCache _cache;
    private readonly SchemaRegistryOptions _options;
    private readonly ILogger<SchemaRegistryService> _logger;

    public SchemaRegistryService(
        IOptions<SchemaRegistryOptions> options,
        IMemoryCache cache,
        ILogger<SchemaRegistryService> logger)
    {
        _options = options.Value;
        _cache = cache;
        _logger = logger;

        _glueClient = new AmazonGlueClient(
            RegionEndpoint.GetBySystemName(_options.Region));
    }

    public async Task<string> RegisterSchemaAsync<T>(
        string schemaName,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Generate JSON schema from type
            var schemaDefinition = GenerateJsonSchema<T>();

            var request = new RegisterSchemaVersionRequest
            {
                SchemaId = new SchemaId
                {
                    RegistryName = _options.RegistryName,
                    SchemaName = schemaName
                },
                SchemaDefinition = schemaDefinition
            };

            var response = await _glueClient.RegisterSchemaVersionAsync(request, cancellationToken);

            _logger.LogInformation(
                "Registered schema {SchemaName} version {VersionNumber}",
                schemaName,
                response.VersionNumber);

            return response.SchemaVersionId;
        }
        catch (AlreadyExistsException)
        {
            _logger.LogDebug("Schema {SchemaName} already exists", schemaName);
            return await GetSchemaVersionIdAsync(schemaName, cancellationToken);
        }
    }

    public async Task<SchemaVersionMetadata> GetSchemaAsync(
        string schemaName,
        CancellationToken cancellationToken = default)
    {
        var cacheKey = $"schema:{schemaName}";

        if (_cache.TryGetValue<SchemaVersionMetadata>(cacheKey, out var cachedSchema))
        {
            return cachedSchema;
        }

        var request = new GetSchemaVersionRequest
        {
            SchemaId = new SchemaId
            {
                RegistryName = _options.RegistryName,
                SchemaName = schemaName
            },
            SchemaVersionNumber = new SchemaVersionNumber { LatestVersion = true }
        };

        var response = await _glueClient.GetSchemaVersionAsync(request, cancellationToken);

        var metadata = new SchemaVersionMetadata
        {
            SchemaVersionId = response.SchemaVersionId,
            SchemaArn = response.SchemaArn,
            VersionNumber = response.VersionNumber,
            SchemaDefinition = response.SchemaDefinition
        };

        _cache.Set(cacheKey, metadata, TimeSpan.FromMinutes(_options.CacheTtlMinutes));

        return metadata;
    }

    public async Task ValidateCompatibilityAsync<T>(
        string schemaName,
        CancellationToken cancellationToken = default)
    {
        var newSchemaDefinition = GenerateJsonSchema<T>();

        var request = new CheckSchemaVersionValidityRequest
        {
            SchemaDefinition = newSchemaDefinition,
            DataFormat = DataFormat.JSON
        };

        var response = await _glueClient.CheckSchemaVersionValidityAsync(request, cancellationToken);

        if (!response.Valid)
        {
            throw new SchemaValidationException(
                $"Schema {schemaName} validation failed: {response.Error}");
        }

        _logger.LogInformation("Schema {SchemaName} compatibility validated", schemaName);
    }

    private string GenerateJsonSchema<T>()
    {
        // Simple JSON schema generation (use NJsonSchema for production)
        var type = typeof(T);
        var schema = new
        {
            title = type.Name,
            type = "object",
            properties = type.GetProperties().ToDictionary(
                p => p.Name,
                p => new { type = GetJsonType(p.PropertyType) }
            )
        };

        return JsonSerializer.Serialize(schema);
    }

    private string GetJsonType(Type type)
    {
        if (type == typeof(string)) return "string";
        if (type == typeof(int) || type == typeof(long)) return "integer";
        if (type == typeof(bool)) return "boolean";
        if (type == typeof(decimal) || type == typeof(double)) return "number";
        if (type == typeof(DateTime)) return "string"; // ISO 8601
        return "object";
    }

    private async Task<string> GetSchemaVersionIdAsync(
        string schemaName,
        CancellationToken cancellationToken)
    {
        var schema = await GetSchemaAsync(schemaName, cancellationToken);
        return schema.SchemaVersionId;
    }
}

public class SchemaRegistryOptions
{
    public string ServiceUrl { get; set; }
    public string RegistryName { get; set; }
    public string CompatibilityMode { get; set; }
    public int CacheTtlMinutes { get; set; }
    public string Region { get; set; }
}

public class SchemaVersionMetadata
{
    public string SchemaVersionId { get; set; }
    public string SchemaArn { get; set; }
    public long VersionNumber { get; set; }
    public string SchemaDefinition { get; set; }
}

public class SchemaValidationException : Exception
{
    public SchemaValidationException(string message) : base(message) { }
}
```

