### Rate Limiter Service

**RateLimiterService.cs:**

```csharp
using Polly;
using Polly.RateLimiting;
using Microsoft.Extensions.Options;

public interface IRateLimiterService
{
    Task<bool> TryAcquireAsync(string destination, CancellationToken cancellationToken = default);
}

public class RateLimiterService : IRateLimiterService
{
    private readonly Dictionary<string, RateLimiter> _limiters = new();
    private readonly RateLimitingOptions _options;
    private readonly ILogger<RateLimiterService> _logger;

    public RateLimiterService(
        IOptions<RateLimitingOptions> options,
        ILogger<RateLimiterService> logger)
    {
        _options = options.Value;
        _logger = logger;

        // Initialize rate limiters per external system
        foreach (var system in _options.ExternalSystems)
        {
            _limiters[system.Key] = new SlidingWindowRateLimiter(new SlidingWindowRateLimiterOptions
            {
                PermitLimit = system.Value.MessagesPerMinute,
                Window = TimeSpan.FromMinutes(1),
                SegmentsPerWindow = 6,  // 10-second segments
                QueueLimit = system.Value.BurstAllowance
            });
        }

        // Default rate limiter
        _limiters["default"] = new SlidingWindowRateLimiter(new SlidingWindowRateLimiterOptions
        {
            PermitLimit = _options.DefaultMessagesPerMinute,
            Window = TimeSpan.FromMinutes(1),
            SegmentsPerWindow = 6
        });
    }

    public async Task<bool> TryAcquireAsync(string destination, CancellationToken cancellationToken = default)
    {
        var limiter = _limiters.ContainsKey(destination)
            ? _limiters[destination]
            : _limiters["default"];

        var lease = await limiter.AcquireAsync(permitCount: 1, cancellationToken);

        if (!lease.IsAcquired)
        {
            _logger.LogWarning(
                "Rate limit exceeded for destination {Destination}",
                destination);
            return false;
        }

        return true;
    }
}

public class RateLimitingOptions
{
    public int DefaultMessagesPerMinute { get; set; }
    public Dictionary<string, ExternalSystemRateLimit> ExternalSystems { get; set; }
}

public class ExternalSystemRateLimit
{
    public int MessagesPerMinute { get; set; }
    public int BurstAllowance { get; set; }
}
```

