### Phase 3: Implement Event Mapping with AutoMapper

**Step 3.1: Create Mapping Profile**

```csharp
using AutoMapper;

public class IntegrationEventMappingProfile : Profile
{
    public IntegrationEventMappingProfile()
    {
        CreateMap<Claim, ClaimApprovedIntegrationEvent>()
            .ForMember(dest => dest.ClaimId, opt => opt.MapFrom(src => src.Id.ToString()))
            .ForMember(dest => dest.ApprovedAmount, opt => opt.MapFrom(src => src.ClaimAmount))
            .ForMember(dest => dest.ApprovalDate, opt => opt.MapFrom(src => src.UpdatedAt ?? src.CreatedAt))
            .ForMember(dest => dest.ApprovedBy, opt => opt.MapFrom(src => "ClaimsSystem"))
            .ForMember(dest => dest.Timestamp, opt => opt.MapFrom(src => DateTime.UtcNow))
            .ForMember(dest => dest.CorrelationId, opt => opt.MapFrom(src => Guid.NewGuid().ToString()));
    }
}
```

**Step 3.2: Create Event Validator**

```csharp
using FluentValidation;

public class ClaimApprovedEventValidator : AbstractValidator<ClaimApprovedIntegrationEvent>
{
    public ClaimApprovedEventValidator()
    {
        RuleFor(x => x.ClaimId).NotEmpty();
        RuleFor(x => x.ClaimNumber).NotEmpty().MaximumLength(50);
        RuleFor(x => x.MemberId).NotEmpty().MaximumLength(50);
        RuleFor(x => x.ProviderId).NotEmpty().MaximumLength(50);
        RuleFor(x => x.ApprovedAmount).GreaterThan(0);
        RuleFor(x => x.ApprovalDate).LessThanOrEqualTo(DateTime.UtcNow);
        RuleFor(x => x.EventVersion).NotEmpty().Matches(@"^\d+\.\d+\.\d+$");
        RuleFor(x => x.CorrelationId).NotEmpty();
    }
}
