### Phase 4: Complete Integration Publisher Implementation

**Step 4.1: Integration Event Publisher Service**

```csharp
using MassTransit;
using AutoMapper;
using FluentValidation;
using System.Diagnostics;

public interface IIntegrationEventPublisher
{
    Task PublishClaimApprovedAsync(Claim claim, CancellationToken cancellationToken = default);
}

public class IntegrationEventPublisher : IIntegrationEventPublisher
{
    private readonly IPublishEndpoint _publishEndpoint;
    private readonly IMapper _mapper;
    private readonly IValidator<ClaimApprovedIntegrationEvent> _validator;
    private readonly ISchemaRegistryService _schemaRegistry;
    private readonly IRateLimiterService _rateLimiter;
    private readonly ILogger<IntegrationEventPublisher> _logger;
    private static readonly ActivitySource ActivitySource = new("IntegrationPublisher");

    public IntegrationEventPublisher(
        IPublishEndpoint publishEndpoint,
        IMapper mapper,
        IValidator<ClaimApprovedIntegrationEvent> validator,
        ISchemaRegistryService schemaRegistry,
        IRateLimiterService rateLimiter,
        ILogger<IntegrationEventPublisher> logger)
    {
        _publishEndpoint = publishEndpoint;
        _mapper = mapper;
        _validator = validator;
        _schemaRegistry = schemaRegistry;
        _rateLimiter = rateLimiter;
        _logger = logger;
    }

    public async Task PublishClaimApprovedAsync(Claim claim, CancellationToken cancellationToken = default)
    {
        using var activity = ActivitySource.StartActivity("PublishClaimApproved");
        activity?.SetTag("claim.id", claim.Id);
        activity?.SetTag("claim.number", claim.ClaimNumber);

        try
        {
            // Step 1: Map domain model to integration event
            var integrationEvent = _mapper.Map<ClaimApprovedIntegrationEvent>(claim);
            integrationEvent.CorrelationId = Guid.NewGuid().ToString();

            _logger.LogInformation(
                "Mapped claim {ClaimId} to integration event with correlation {CorrelationId}",
                claim.Id, integrationEvent.CorrelationId);

            // Step 2: Validate integration event
            var validationResult = await _validator.ValidateAsync(integrationEvent, cancellationToken);
            if (!validationResult.IsValid)
            {
                var errors = string.Join(", ", validationResult.Errors.Select(e => e.ErrorMessage));
                throw new IntegrationEventValidationException(
                    $"Integration event validation failed: {errors}");
            }

            // Step 3: Validate schema compatibility
            await _schemaRegistry.ValidateCompatibilityAsync<ClaimApprovedIntegrationEvent>(
                "ClaimApproved", cancellationToken);

            // Step 4: Check rate limits
            const string destination = "PartnerHealthNet";
            var canPublish = await _rateLimiter.TryAcquireAsync(destination, cancellationToken);

            if (!canPublish)
            {
                _logger.LogWarning(
                    "Rate limit exceeded for destination {Destination}, event will be queued in outbox",
                    destination);

                // Event will remain in outbox until rate limit allows
                throw new RateLimitExceededException(
                    $"Rate limit exceeded for destination {destination}");
            }

            // Step 5: Publish to outbox (MassTransit handles outbox commit)
            await _publishEndpoint.Publish(integrationEvent, context =>
            {
                // Set message headers
                context.MessageId = Guid.NewGuid();
                context.CorrelationId = Guid.Parse(integrationEvent.CorrelationId);
                context.Headers.Set("event-type", integrationEvent.EventType);
                context.Headers.Set("event-version", integrationEvent.EventVersion);
                context.Headers.Set("source-system", integrationEvent.SourceSystem);
                context.Headers.Set("timestamp", integrationEvent.Timestamp.ToString("O"));

                // Propagate W3C trace context
                if (Activity.Current != null)
                {
                    context.Headers.Set("traceparent", Activity.Current.Id);
                    if (Activity.Current.TraceStateString != null)
                    {
                        context.Headers.Set("tracestate", Activity.Current.TraceStateString);
                    }
                }

                // Set destination routing (transport-specific)
                context.SetRoutingKey($"claims.approved.{claim.MemberId}");
            }, cancellationToken);

            _logger.LogInformation(
                "Published ClaimApproved event for claim {ClaimId} with correlation {CorrelationId}",
                claim.Id, integrationEvent.CorrelationId);

            activity?.SetTag("publish.status", "success");
        }
        catch (IntegrationEventValidationException ex)
        {
            _logger.LogError(ex,
                "Validation failed for claim {ClaimId}: {Error}",
                claim.Id, ex.Message);

            activity?.SetTag("publish.status", "validation_failed");
            activity?.SetTag("error.message", ex.Message);
            throw;
        }
        catch (RateLimitExceededException ex)
        {
            _logger.LogWarning(ex,
                "Rate limit exceeded for claim {ClaimId}",
                claim.Id);

            activity?.SetTag("publish.status", "rate_limited");
            throw;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Failed to publish ClaimApproved event for claim {ClaimId}",
                claim.Id);

            activity?.SetTag("publish.status", "failed");
            activity?.SetTag("error.message", ex.Message);
            throw;
        }
    }
}

public class IntegrationEventValidationException : Exception
{
    public IntegrationEventValidationException(string message) : base(message) { }
}

public class RateLimitExceededException : Exception
{
    public RateLimitExceededException(string message) : base(message) { }
}
```

**Step 4.2: Domain Service with Transactional Outbox**

```csharp
using Microsoft.EntityFrameworkCore;

public class ClaimService
{
    private readonly ApplicationDbContext _dbContext;
    private readonly IIntegrationEventPublisher _eventPublisher;
    private readonly ILogger<ClaimService> _logger;

    public ClaimService(
        ApplicationDbContext dbContext,
        IIntegrationEventPublisher eventPublisher,
        ILogger<ClaimService> logger)
    {
        _dbContext = dbContext;
        _eventPublisher = eventPublisher;
        _logger = logger;
    }

    public async Task ApproveClaimAsync(Guid claimId, CancellationToken cancellationToken = default)
    {
        using var transaction = await _dbContext.Database.BeginTransactionAsync(cancellationToken);

        try
        {
            // Step 1: Load claim
            var claim = await _dbContext.Claims
                .FirstOrDefaultAsync(c => c.Id == claimId, cancellationToken);

            if (claim == null)
            {
                throw new ClaimNotFoundException($"Claim {claimId} not found");
            }

            // Step 2: Update claim status (domain logic)
            claim.Status = ClaimStatus.Approved;
            claim.UpdatedAt = DateTime.UtcNow;

            _dbContext.Claims.Update(claim);

            // Step 3: Publish integration event to outbox (SAME TRANSACTION)
            // MassTransit will write event to OutboxMessage table
            await _eventPublisher.PublishClaimApprovedAsync(claim, cancellationToken);

            // Step 4: Commit both claim update and outbox insert atomically
            await _dbContext.SaveChangesAsync(cancellationToken);
            await transaction.CommitAsync(cancellationToken);

            _logger.LogInformation(
                "Claim {ClaimId} approved and integration event added to outbox",
                claimId);
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync(cancellationToken);
            _logger.LogError(ex, "Failed to approve claim {ClaimId}", claimId);
            throw;
        }
    }
}

public class ClaimNotFoundException : Exception
{
    public ClaimNotFoundException(string message) : base(message) { }
}
